cat > 'hook.mbtx' <<'MBTEOF'
import { "moonbitlang/core/env" }
fn main {
  guard @env.get_env_var("MOON_BACKEND") == Some("native") else { abort("backend must be native") }
  guard @env.get_env_var("MOON_PROFILE") == Some("debug") else { abort("profile must be debug") }
  for key in ["MOON_MOD", "MOON_BUILD_DIR", "MOON_HOST_OS", "MOON_HOST_ARCH", "MOON_JOBS"] {
    guard @env.get_env_var(key) is Some(value) && value.length() > 0 else { abort("missing build environment") }
  }
  println("{}")
}
MBTEOF

